// Shape of records written to dist/aiux-json/<table>_<sysId>.json by
// @servicenow/aiux-sdk's writeMetadataJson during the prebuild step.
export type AiuxFieldPlain = { value: string }
export type AiuxFieldCdata = { isCdata: true; value: string }
export type AiuxFieldRef = { isRef: true; table: string; nowIdKey?: string; explicitSysId?: string }
// Used for fields that take an array of plain values (e.g. an Acl's `roles`).
export type AiuxFieldArray = { values: string[] }
export type AiuxFieldValue = AiuxFieldPlain | AiuxFieldCdata | AiuxFieldRef | AiuxFieldArray

export type AiuxRecordMetadata = {
    // Omitted when `fluentPlugin` routes to a dedicated plugin (e.g. 'Acl') - the
    // target table is implied by the plugin being delegated to and isn't carried here.
    table?: string
    fields: Record<string, AiuxFieldValue>
    nowIdKey: string
    uniqueKey: string
    explicitSysId?: string
    sysIdSourceKey?: string
    demo_install: boolean
    sourceFiles: string[]
    fluentPlugin?: string | null
}
